create or replace function public.open_result_dispute(p_result_id uuid,p_reason_code text,p_description text,p_evidence_object_ids uuid[],p_idempotency_key uuid)returns table(dispute_id uuid,status text,calculation_version bigint,version bigint)language plpgsql security definer set search_path=pg_catalog,public,private as $$declare v_actor uuid:=public.current_player_id();v_club uuid;begin select r.club_id into v_club from public.match_results r join public.match_participants mp on mp.match_id=r.match_id where r.id=p_result_id and mp.player_id=v_actor for update;if v_club is null then raise exception using errcode='P0001',detail='PERMISSION_DENIED';end if;insert into public.result_disputes(result_id,club_id,opened_by,reason_code,description)values(p_result_id,v_club,v_actor,p_reason_code,p_description)returning id,public.result_disputes.status::text,public.result_disputes.version into dispute_id,status,version;update public.match_results set status='disputed',version=public.match_results.version+1 where id=p_result_id;update public.official_results set effect_state='suspended' where match_id=(select match_id from public.match_results where id=p_result_id);calculation_version:=private.rebuild_competition_after_dispute(p_result_id);insert into public.dispute_evidence select dispute_id,id,v_actor,now()from private.evidence_objects where id=any(coalesce(p_evidence_object_ids,'{}'))and owner_player_id=v_actor;insert into private.audit_log(actor_auth_user_id,action,aggregate_type,aggregate_id,club_id,request_id)values(auth.uid(),'dispute.opened','result_dispute',dispute_id,v_club,p_idempotency_key);return next;exception when unique_violation then raise exception using errcode='P0001',detail='DISPUTE_ALREADY_OPEN';end$$;
create or replace function public.resolve_result_dispute(p_dispute_id uuid,p_resolution text,p_corrected_score jsonb,p_reason text,p_idempotency_key uuid)returns table(dispute_id uuid,result_status text,revision_id uuid,calculation_version bigint)language plpgsql security definer set search_path=pg_catalog,public,private as $$declare v public.result_disputes%rowtype;v_result public.match_results%rowtype;v_actor uuid:=public.current_player_id();begin select * into v from public.result_disputes where id=p_dispute_id and status='open' for update;if v.id is null then raise exception using errcode='P0001',detail='DISPUTE_NOT_OPEN';end if;if not private.has_club_role(v.club_id,array['owner','score_official']::public.club_role[])then raise exception using errcode='P0001',detail='PERMISSION_DENIED';end if;select * into v_result from public.match_results where id=v.result_id for update;if p_resolution='corrected'then insert into public.result_revisions(result_id,match_id,revision_no,score,score_digest,winner_side,status,submitted_by,reason,request_id)select v_result.id,v_result.match_id,max(revision_no)+1,p_corrected_score,encode(extensions.digest(p_corrected_score::text,'sha256'),'hex'),case when (p_corrected_score#>>'{games,0,sideA}')::int>(p_corrected_score#>>'{games,0,sideB}')::int then 1 else 2 end,'accepted',v_actor,p_reason,p_idempotency_key from public.result_revisions where result_id=v_result.id returning id into revision_id;update public.match_results set current_revision_id=revision_id,status='finalized',version=version+1 where id=v_result.id;update public.official_results set authoritative_revision_id=revision_id,effect_state='active' where match_id=v_result.match_id;elsif p_resolution='voided'then update public.match_results set status='voided',version=version+1 where id=v_result.id;update public.official_results set effect_state='none' where match_id=v_result.match_id;else update public.match_results set status='finalized',version=version+1 where id=v_result.id;update public.official_results set effect_state=case when exists(select 1 from public.matches where id=v_result.match_id and record_class='ranked')then'active'::public.ranked_effect_state else'none'::public.ranked_effect_state end where match_id=v_result.match_id;end if;update public.result_disputes set status='resolved',resolution=p_resolution::public.dispute_resolution,resolution_reason=p_reason,resolved_by=v_actor,resolved_at=now(),version=version+1 where id=v.id;calculation_version:=private.rebuild_competition_after_dispute(v.result_id);dispute_id:=v.id;select status::text into result_status from public.match_results where id=v.result_id;insert into private.audit_log(actor_auth_user_id,action,aggregate_type,aggregate_id,club_id,request_id)values(auth.uid(),'dispute.resolved','result_dispute',v.id,v.club_id,p_idempotency_key);return next;end$$;
revoke all on function public.open_result_dispute(uuid,text,text,uuid[],uuid),public.resolve_result_dispute(uuid,text,jsonb,text,uuid)from public;grant execute on function public.open_result_dispute(uuid,text,text,uuid[],uuid),public.resolve_result_dispute(uuid,text,jsonb,text,uuid)to authenticated;
